-- Recipe tags become a fixed list (see `tagKeys` in packages/schemas).
-- Known spellings ("Italian", "italienisch", "Vegan", "Under 30 min") are mapped to their key.
-- A tag that is not in the list is dropped. The result is in the order of the list.
-- Generated from `tagSpellings`; do not edit the spelling list by hand.

CREATE TEMP TABLE "tag_spelling" ("spelling" text PRIMARY KEY, "key" text NOT NULL, "position" integer NOT NULL);
--> statement-breakpoint
--> statement-breakpoint
UPDATE "recipe" SET "tags" = ARRAY(
  SELECT found."key"
  FROM "tag_spelling" AS found
  WHERE found."spelling" IN (
    SELECT btrim(regexp_replace(regexp_replace(lower(own), '[-_\s]+', ' ', 'g'), '\.$', '')) FROM unnest("recipe"."tags") AS own
  )
  GROUP BY found."key", found."position"
  ORDER BY found."position"
);
--> statement-breakpoint
DROP TABLE "tag_spelling";
